        'yasli-bakim-demansta-banyo-direnci' => ['alzheimer-ve-demans', 'Demansta Banyo ve Kişisel Bakım Direnci', 'Demans yaşayan yakınların banyo yapmak istememesinin nedenleri, banyoyu daha kolay hale getiren yöntemler, mahremiyet ve güvenlik önerileri.'],
