        'yasli-bakim-demans-bakiminda-destek' => ['alzheimer-ve-demans', 'Demans Bakımında Destek Almak', 'Demanslı yakınına bakan aileler için destek kaynakları: aile içi paylaşım, profesyonel hizmetler, gündüzlü bakım, destek grupları ve bakım verenin kendi sağlığı.'],
        'yasli-bakim-yasli-haklari-genel' => ['haklar-ve-destekler', 'Yaşlıların Yararlanabileceği Haklar: Genel Rehber', 'Yaşlı bireylerin yararlanabileceği sosyal, sağlık, ulaşım ve bakım haklarının genel çerçevesi; başvuru yolları ve güncel bilgiye ulaşma önerileri.'],
        'yasli-bakim-yaslilar-icin-engelli-raporu' => ['haklar-ve-destekler', 'Yaşlılar İçin Sağlık Kurulu Raporu Neden Önemli?', 'Yaşa bağlı hastalıklar ve bakım ihtiyacı olan yaşlılar için sağlık kurulu raporunun önemi, hangi haklarla bağlantılı olabileceği ve başvuru öncesi hazırlık.'],
        'yasli-bakim-vasi-tayini' => ['haklar-ve-destekler', 'Vasi Tayini Nedir, Nasıl Yapılır?', 'Kendi işlerini yürütemeyecek duruma gelen yaşlılar için vasi tayininin anlamı, ne zaman gerekebileceği, sürecin genel işleyişi ve ailelerin dikkat etmesi gerekenler.'],
        'yasli-bakim-vekaletname' => ['haklar-ve-destekler', 'Yaşlı Yakın İçin Vekaletname: Ne Zaman Gerekir?', 'Yaşlı anne babanın işlerini yürütmek için vekaletname ne zaman gerekir, nasıl verilir, kapsamı nasıl belirlenir ve nelere dikkat edilmelidir?'],
        'yasli-bakim-alo-183' => ['haklar-ve-destekler', 'Alo 183 Hattı Hangi Konularda Yardımcı Olur?', 'Alo 183 sosyal destek hattının yaşlılar ve aileleri için sunduğu bilgilendirme ve yönlendirme hizmetleri, arama öncesi hazırlık ve ne zaman aranabileceği.'],
        'yasli-bakim-sosyal-yardim-basvurulari' => ['haklar-ve-destekler', 'Yaşlılar İçin Sosyal Yardım Başvuruları', 'İhtiyaç sahibi yaşlıların başvurabileceği sosyal yardımların genel çerçevesi, başvuru yerleri, hazırlanması gereken belgeler ve başvuru sonrası süreç.'],
        'yasli-bakim-tibbi-malzeme-odemeleri' => ['haklar-ve-destekler', 'Yaşlılar İçin Tıbbi Malzeme ve Cihaz Ödemeleri', 'Hasta yatağı, tekerlekli sandalye, hasta bezi, işitme cihazı gibi tıbbi malzemelerin teminine ilişkin genel süreç, rapor ve reçete, tedarikçi seçimi ve dikkat edilecekler.'],
        'yasli-bakim-ulasim-kolayliklari' => ['haklar-ve-destekler', 'Yaşlılar İçin Ulaşım Kolaylıkları', 'Yaşlıların şehir içi ve şehirlerarası ulaşımda yararlanabileceği kolaylıklar, kart başvuruları, erişilebilir ulaşım ve güvenli yolculuk için öneriler.'],
        'yasli-bakim-yasli-ihmali-ve-istismari' => ['haklar-ve-destekler', 'Yaşlı İhmali ve İstismarı: Belirtiler ve Başvuru Yolları', 'Yaşlılara yönelik ihmal ve istismarın türleri, dikkat edilmesi gereken belirtiler, şüphelenildiğinde yapılacaklar ve başvurulabilecek kurumlar.'],
        'yasli-bakim-banka-islemlerinde-guvenlik' => ['haklar-ve-destekler', 'Yaşlının Banka İşlemlerinde Güvenlik', 'Yaşlı bireylerin banka hesaplarını, kartlarını ve dijital bankacılık işlemlerini güvenle kullanması için öneriler; ailenin destek olma yolları ve şüpheli durumlar.'],
        'yasli-bakim-dolandiricilik' => ['haklar-ve-destekler', 'Yaşlıları Hedef Alan Dolandırıcılıklar', 'Yaşlılara yönelik telefon, kapı ve internet dolandırıcılıklarının yaygın türleri, uyarı işaretleri, korunma yolları ve dolandırıldığında yapılması gerekenler.'],
        'yasli-bakim-belediye-yasli-hizmetleri' => ['haklar-ve-destekler', 'Belediyelerin Yaşlılara Sunduğu Hizmetler', 'Belediyelerin yaşlılar için sunabildiği evde bakım, sosyal etkinlik, yaşlı merkezi, ulaşım, sağlık ve yemek hizmetleri; başvuru ve bilgi alma yolları.'],
        'yasli-bakim-bakim-maliyeti-planlama' => ['haklar-ve-destekler', 'Yaşlı Bakım Maliyetini Planlamak', 'Yaşlı bakımının farklı seçeneklerinde ortaya çıkabilecek giderler, aile bütçesi planlaması, kamusal destekler ve uzun vadeli finansal hazırlık için öneriler.'],
        'yasli-bakim-bakim-masraflarini-paylasmak' => ['haklar-ve-destekler', 'Bakım Masraflarını Aile İçinde Paylaşmak', 'Yaşlı ebeveynin bakım giderlerinin kardeşler arasında adil ve şeffaf paylaşılması, farklı katkı biçimleri, yazılı planlama ve anlaşmazlıkları önleme önerileri.'],
        'yasli-bakim-evde-bakim-destegi-basvuru-hatalari' => ['haklar-ve-destekler', 'Evde Bakım Desteği Başvurusunda Sık Yapılan Hatalar', 'Evde bakım desteği başvurusunda sık karşılaşılan hatalar: rapor, belge, gelir bilgisi, bildirim ve takip konularında dikkat edilmesi gerekenler.'],
        'yasli-bakim-huzurevi-saglik-raporu' => ['haklar-ve-destekler', 'Huzurevi İçin Sağlık Raporu Nasıl Alınır?', 'Huzurevi ve bakımevi kaydında istenen sağlık raporunun amacı, genellikle nereden alındığı, hangi tetkiklerin istenebileceği ve rapor alırken dikkat edilecekler.'],
        'yasli-bakim-kimsesiz-yaslilar-icin-destek' => ['haklar-ve-destekler', 'Kimsesiz Yaşlılar İçin Destek Yolları', 'Bakacak yakını olmayan ya da yalnız kalan yaşlılar için kamusal destekler, huzurevi başvurusu, sosyal yardımlar ve çevrenin rolü hakkında bilgiler.'],
        'yasli-bakim-dusmeleri-onleme' => ['gunluk-yasam', 'Yaşlılarda Düşmeleri Önlemek', 'Yaşlılarda düşme riskini artıran etkenler, evde ve dışarıda alınabilecek önlemler, ayakkabı ve ilaç kontrolü, hareketin önemi ve düşme sonrasında yapılacaklar.'],
        'yasli-bakim-sicak-havalarda-yaslilar' => ['gunluk-yasam', 'Sıcak Havalarda Yaşlıları Korumak', 'Yaz aylarında yaşlıları sıcağın olumsuz etkilerinden korumak için sıvı tüketimi, ev serinliği, giyim, ilaçlar ve dikkat edilmesi gereken uyarı işaretleri.'],
        'yasli-bakim-kis-aylarinda-yasli-bakimi' => ['gunluk-yasam', 'Kış Aylarında Yaşlı Bakımı', 'Kış aylarında yaşlıları soğuk, hastalıklar, kaygan zeminler ve yalnızlıktan korumak için ev ısısı, giyim, beslenme, aşı ve güvenlik önerileri.'],
        'yasli-bakim-yaslilarda-sivi-tuketimi' => ['gunluk-yasam', 'Yaşlılarda Sıvı Tüketimi: Neden Önemli?', 'Yaşlılarda yetersiz sıvı alımının nedenleri, olası etkileri, sıvı tüketimini artırmanın pratik yolları ve dikkat edilmesi gereken belirtiler.'],
        'yasli-bakim-yaslilarda-beslenme' => ['gunluk-yasam', 'Yaşlılarda Dengeli Beslenme', 'Yaşlılıkta beslenme ihtiyaçlarının değişimi, dengeli bir tabakta neler olmalı, iştahsızlık ve çiğneme güçlüğü gibi sorunlar ve beslenmeyi destekleyen pratik öneriler.'],
        'yasli-bakim-yaslilarda-uyku' => ['gunluk-yasam', 'Yaşlılarda Uyku Düzeni', 'Yaşlılıkta uykudaki değişiklikler, uykuyu bozan etkenler, sağlıklı uyku alışkanlıkları ve doktora danışılması gereken durumlar.'],
        'yasli-bakim-yaslilar-icin-gunluk-hareket' => ['gunluk-yasam', 'Yaşlılar İçin Günlük Hareket', 'Yaşlılıkta düzenli hareketin faydaları, güvenli hareket önerileri, ev içinde yapılabilecek basit etkinlikler, motivasyon ve doktora danışmanın önemi.'],
        'yasli-bakim-yaslilikta-yalnizlik' => ['gunluk-yasam', 'Yaşlılıkta Yalnızlıkla Mücadele', 'Yaşlılarda yalnızlığın nedenleri ve etkileri, ailenin ve çevrenin rolü, sosyal etkinlikler, teknoloji ile bağ kurma ve gönüllü programlar hakkında öneriler.'],
        'yasli-bakim-yaslilara-teknoloji' => ['gunluk-yasam', 'Yaşlılara Teknoloji Kullanımını Öğretmek', 'Akıllı telefon, tablet ve görüntülü görüşme gibi teknolojileri yaşlılara öğretmek için sabırlı bir yaklaşım, basitleştirilmiş ayarlar, güvenlik ve dolandırıcılık uyarıları.'],
        'yasli-bakim-acil-durum-butonu' => ['gunluk-yasam', 'Acil Durum Butonu ve Takip Cihazları', 'Yalnız yaşayan ya da düşme riski olan yaşlılar için acil durum butonları, düşme algılayan cihazlar ve konum takip araçları; seçim ve kullanımda dikkat edilecekler.'],
        'yasli-bakim-yaslilar-icin-hobiler' => ['gunluk-yasam', 'Yaşlılar İçin Hobi ve Uğraş Önerileri', 'Yaşlılıkta hobi edinmenin faydaları; el işleri, bahçecilik, müzik, okuma, oyunlar ve topluluk etkinlikleri gibi öneriler ve fiziksel durumuna uygun seçim.'],
        'yasli-bakim-isitme-guclugu-iletisim' => ['gunluk-yasam', 'İşitme Güçlüğü Olan Yaşlıyla İletişim', 'İşitme kaybı yaşayan yaşlılarla daha etkili iletişim kurmanın yolları, işitme cihazı kullanımı, ortam düzenlemeleri ve sosyal hayattan kopmayı önleme önerileri.'],
        'yasli-bakim-gorme-guclugu-ev-duzeni' => ['gunluk-yasam', 'Görme Güçlüğü Olan Yaşlı İçin Ev Düzeni', 'Görme kaybı yaşayan yaşlıların evde güvenle ve bağımsız yaşamasını kolaylaştıran aydınlatma, kontrast, düzen ve yardımcı araç önerileri.'],
        'yasli-bakim-yasli-ile-seyahat' => ['gunluk-yasam', 'Yaşlı Yakınla Seyahat Ederken', 'Yaşlı bir yakınla seyahat planlarken sağlık hazırlığı, ilaçlar, ulaşım seçimi, konaklama, dinlenme molaları ve özel ihtiyaçlar için öneriler.'],
        'yasli-bakim-bayram-ve-ozel-gunler' => ['gunluk-yasam', 'Bayramlarda ve Özel Günlerde Yaşlı Yakınlar', 'Bayram, doğum günü ve özel günlerde yaşlı yakınları sürece dahil etmek; huzurevindeki yakınları ziyaret, kalabalık ortamlar, yalnızlık ve sağlık konularında öneriler.'],
        'yasli-bakim-hastane-sonrasi-eve-donus' => ['gunluk-yasam', 'Hastaneden Eve Dönüşte Bakım Planı', 'Yaşlı bir yakın hastaneden taburcu olurken bilgi toplama, ev hazırlığı, ilaç düzeni, kontrol randevuları, bakım desteği ve dikkat edilmesi gereken işaretler.'],
        'yasli-bakim-agiz-ve-dis-bakimi' => ['gunluk-yasam', 'Yaşlılarda Ağız ve Diş Bakımı', 'Yaşlılıkta ağız ve diş sağlığının önemi, günlük bakım, protez temizliği, bakım verenin desteği ve diş hekimi kontrolleri hakkında öneriler.'],
        'yasli-bakim-bakim-veren-tukenmisligi' => ['aile-ve-bakim-veren', 'Bakım Veren Tükenmişliği: İşaretler ve Çözümler', 'Yaşlı yakınına bakan aile üyelerinde tükenmişliğin işaretleri, nedenleri, önleme yolları, destek kaynakları ve profesyonel yardım almanın önemi.'],
        'yasli-bakim-kardesler-arasi-bakim-paylasimi' => ['aile-ve-bakim-veren', 'Kardeşler Arasında Bakım Sorumluluğunu Paylaşmak', 'Yaşlı anne babanın bakımında kardeşler arasında adil görev paylaşımı, farklı katkı biçimleri, iletişim, anlaşmazlıkları önleme ve aile toplantıları.'],
        'yasli-bakim-calisan-bakim-veren' => ['aile-ve-bakim-veren', 'Çalışırken Yaşlı Yakına Bakmak', 'Çalışma hayatı ile yaşlı yakının bakımını birlikte sürdürmek için planlama, işverenle iletişim, destek hizmetleri, teknoloji ve bakım verenin kendi sağlığı.'],
        'yasli-bakim-bakim-kararinda-sucluluk' => ['aile-ve-bakim-veren', 'Bakım Kararlarında Suçluluk Duygusu', 'Yaşlı yakın için bakım kararları verirken yaşanan suçluluk duygusunun nedenleri, kararın gerekçelerini hatırlamak, duygularla başa çıkma ve destek almak.'],
        'yasli-bakim-anne-babaya-bakmak' => ['aile-ve-bakim-veren', 'Anne Babaya Bakmak: Rol Değişimi', 'Yetişkin çocukların yaşlanan anne babalarına bakım verirken yaşadığı rol değişimi, duygusal zorluklar, saygı ve özerkliği korumak, sınırlar ve kendine bakım.'],
        'yasli-bakim-zor-konusmalar' => ['aile-ve-bakim-veren', 'Yaşlı Yakınla Zor Konuşmalar', 'Araç kullanmayı bırakmak, bakım desteği almak, huzurevi, mali konular ve sağlık kararları gibi zor konuları yaşlı yakınla konuşmak için öneriler.'],
        'yasli-bakim-bakim-verene-mola' => ['aile-ve-bakim-veren', 'Bakım Verenin Mola İhtiyacı', 'Yaşlı yakınına bakan aile üyelerinin dinlenme ihtiyacı, mola seçenekleri, molayı planlamak, suçluluk duygusu ve düzenli dinlenmenin bakıma etkisi.'],
        'yasli-bakim-aile-toplantisi' => ['aile-ve-bakim-veren', 'Yaşlı Bakımı İçin Aile Toplantısı Nasıl Yapılır?', 'Yaşlı bir yakının bakım ihtiyacı ortaya çıktığında aile toplantısı düzenlemek: hazırlık, gündem, yaşlının katılımı, görev paylaşımı, anlaşmazlıklar ve kararların yazıya dökülmesi.'],
        'yasli-bakim-torunlar-ve-bakim' => ['aile-ve-bakim-veren', 'Torunlar ve Yaşlı Bakımı: Çocuklarla Nasıl Konuşulur?', 'Büyükanne ve büyükbabanın bakım ihtiyacı arttığında torunlara durumu anlatmak, yaşa uygun açıklamalar, demans ve hastalık hakkında konuşmak, bağı korumak ve gençlerin katkısı.'],
        'yasli-bakim-baska-sehirden-bakim' => ['aile-ve-bakim-veren', 'Başka Şehirden Yaşlı Bakımını Organize Etmek', 'Farklı bir şehirde yaşayan yaşlı anne babanın bakımını uzaktan organize etmek: yerel destek ağı, teknoloji, düzenli iletişim, ziyaret planlaması, acil durum hazırlığı ve bakım veren yükü.'],
        'yasli-bakim-bakim-defteri' => ['aile-ve-bakim-veren', 'Bakım Defteri: Yaşlı Bakımında Düzenli Kayıt Tutmak', 'Yaşlı bakımında bakım defteri tutmanın faydaları, deftere neler yazılmalı, ilaç ve sağlık kayıtları, birden fazla bakım veren arasında bilgi aktarımı ve dijital seçenekler.'],
        'yasli-bakim-yaslinin-ozerkligi' => ['aile-ve-bakim-veren', 'Yaşlının Özerkliğine Saygı: Bakım ve Bağımsızlık Dengesi', 'Yaşlı bakımında özerkliğe saygının önemi, karar süreçlerine katılım, güvenlik ile bağımsızlık arasındaki denge, aşırı korumacılığın riskleri ve demansta özerklik.'],
        'yasli-bakim-bakim-verenlere-destek-kaynaklari' => ['aile-ve-bakim-veren', 'Bakım Verenler İçin Destek Kaynakları', 'Yaşlı yakınına bakan aile üyelerinin yararlanabileceği destek kaynakları: kamu ve belediye hizmetleri, gündüzlü bakım, kısa süreli konaklama, destek grupları, eğitimler ve psikolojik destek.'],
        'yasli-bakim-yasli-yakini-eve-almak' => ['aile-ve-bakim-veren', 'Yaşlı Yakını Eve Almak: Karar ve Hazırlık', 'Yaşlı anne baba ya da yakını kendi evine almayı düşünen aileler için karar süreci, aile içi konuşmalar, ev düzenlemesi, mahremiyet, iş bölümü ve dış destek planlaması.'],
        'yasli-bakim-kayip-sonrasi-yas' => ['aile-ve-bakim-veren', 'Bakım Verdiğiniz Yakını Kaybettikten Sonra Yas Süreci', 'Uzun süre bakım verdiği yakınını kaybeden kişilerin yas süreci: yaşanabilecek duygular, rahatlama ve suçluluk, günlük düzene dönüş, pratik işler, destek almak ve kendine zaman tanımak.'],
        'yasli-bakim-palyatif-bakim-nedir' => ['aile-ve-bakim-veren', 'Palyatif Bakım Nedir? Aileler İçin Genel Bilgiler', 'Palyatif bakımın amacı, kimlerin yararlanabileceği, hangi ortamlarda verilebileceği, ekip yaklaşımı, ailenin rolü ve bakım verenlerin destek ihtiyacı hakkında genel bilgiler.'],
    ],
    'bakimevleri' => [
        'cocuk-kres-ziyaret-kontrol-listesi' => ['kres-ve-anaokulu-secimi', 'Kreş Ziyaretinde Kontrol Listesi', 'Kreşi yerinde gezerken nelere bakmalı? Sınıflar, güvenlik, temizlik, öğretmenler ve günlük düzen için yanınıza alabileceğiniz pratik liste.'],
        'cocuk-kres-guvenlik-onlemleri' => ['kres-ve-anaokulu-secimi', 'Kreşte Güvenlik: Nelere Bakılmalı?', 'Kreşte çocuk güvenliği için bina, giriş-çıkış, teslim kuralları, oyun alanı ve acil durum hazırlığı açısından kontrol edilmesi gerekenler.'],
        'cocuk-kres-ogretmen-cocuk-orani' => ['kres-ve-anaokulu-secimi', 'Öğretmen Başına Çocuk Sayısı Neden Önemli?', 'Kreşte bir öğretmenin kaç çocukla ilgilendiği; güvenlik, gelişim ve bireysel ilgi açısından neden önemlidir? Velilerin sorması gerekenler.'],
        'cocuk-kres-hijyen' => ['kres-ve-anaokulu-secimi', 'Kreşte Hijyen ve Temizlik: Nelere Dikkat Edilmeli?', 'Kreşte hijyen neden önemli? Tuvalet, bez değiştirme alanı, mutfak, oyuncak temizliği ve hastalık dönemlerinde alınan önlemler hakkında bilmeniz gerekenler.'],
        'cocuk-kres-kamera-sistemi' => ['kres-ve-anaokulu-secimi', 'Kreşte Kamera Sistemi: Artıları ve Sınırları', 'Kreşlerde kamera sistemi ve velilerin canlı izleme imkânı ne sağlar, nelere dikkat edilmeli? Mahremiyet, güven ve iletişim açısından değerlendirme.'],
        'cocuk-montessori-kres' => ['kres-ve-anaokulu-secimi', 'Montessori Yaklaşımlı Kreş Nedir?', 'Montessori yaklaşımının temel ilkeleri, Montessori kreşlerinde sınıf düzeni ve günlük işleyiş, seçim yaparken sorulacak sorular.'],
        'cocuk-yarim-gun-tam-gun-kres' => ['kres-ve-anaokulu-secimi', 'Yarım Gün mü, Tam Gün mü Kreş?', 'Çocuğunuz için yarım gün mü tam gün mü kreş daha uygun? Yaş, uyum, aile düzeni ve bütçe açısından iki seçeneğin karşılaştırması.'],
        'cocuk-ev-yakini-mi-is-yakini-mi' => ['kres-ve-anaokulu-secimi', 'Kreş Ev Yakını mı, İş Yeri Yakını mı Olmalı?', 'Kreş seçiminde konum neden önemli? Eve yakın ve iş yerine yakın kreşin avantajları, yol süresi, hastalık günleri ve sosyal çevre açısından karşılaştırma.'],
        'cocuk-kres-bahce-ve-oyun-alani' => ['kres-ve-anaokulu-secimi', 'Kreşte Bahçe ve Oyun Alanının Önemi', 'Açık havada oyun çocuğun gelişimine nasıl katkı sağlar? Kreşin bahçe ve oyun alanını değerlendirirken güvenlik, kullanım sıklığı ve olanaklar açısından bakılacaklar.'],
        'cocuk-kres-yemek-menusu-degerlendirme' => ['kres-ve-anaokulu-secimi', 'Kreş Yemek Menüsü Nasıl Değerlendirilir?', 'Kreşin yemek menüsünde nelere bakmalı? Öğün düzeni, çeşitlilik, şeker ve tuz kullanımı, alerji yönetimi ve yemek ortamı hakkında velilere öneriler.'],
        'cocuk-kres-ogretmen-niteligi' => ['kres-ve-anaokulu-secimi', 'İyi Bir Kreş Öğretmeninde Aranacak Özellikler', 'Kreş öğretmeninin eğitimi, deneyimi, çocuklarla iletişimi ve velilerle iş birliği açısından aranacak özellikler; görüşmede gözlemleyebileceğiniz ipuçları.'],
        'cocuk-kres-yorumlari' => ['kres-ve-anaokulu-secimi', 'Kreş Yorumlarını Doğru Okumak', 'İnternetteki kreş ve anaokulu yorumlarını değerlendirirken nelere dikkat etmeli? Güncellik, ayrıntı, ortak şikâyetler ve yerinde doğrulama önerileri.'],
        'cocuk-kres-degistirmek' => ['kres-ve-anaokulu-secimi', 'Kreş Değiştirmek Gerekir mi? Dikkat Edilecek İşaretler', 'Çocuğunuzun kreşi değiştirilmeli mi? Uyum sorunu ile ciddi sorunu ayırt etmek, kreşle konuşmak ve geçişi kolaylaştırmak için öneriler.'],
        'cocuk-bebek-kresi' => ['kres-ve-anaokulu-secimi', 'Bebek Kreşi (0-2 Yaş) Seçerken Nelere Dikkat Edilmeli?', 'Bebek kreşi seçerken bakım personeli, uyku ve beslenme düzeni, hijyen, güvenlik ve aile ile iletişim açısından dikkat edilmesi gerekenler.'],
        'cocuk-ingilizce-egitimli-kres' => ['kres-ve-anaokulu-secimi', 'İngilizce Eğitimli Kreş: Beklentiler ve Gerçekler', 'Kreşte yabancı dil eğitimi nasıl verilir, okul öncesi dönemde neler beklenebilir? İngilizce programını değerlendirirken sorulacak sorular.'],
        'cocuk-kres-servis-guvenligi' => ['kres-ve-anaokulu-secimi', 'Kreş Servisinde Güvenlik: Velilerin Bilmesi Gerekenler', 'Kreş servisi kullanacak aileler için araç, sürücü, rehber personel, çocuk koltuğu ve iniş-biniş kuralları hakkında kontrol listesi.'],
        'cocuk-is-yeri-kresi' => ['kres-ve-anaokulu-secimi', 'İş Yeri Kreşleri: Avantajları ve Dikkat Edilecekler', 'İş yeri kreşi ya da işverenin anlaştığı kreşler çalışan ebeveynlere ne sağlar? Avantajlar, sınırlılıklar ve karar verirken sorulacak sorular.'],
        'cocuk-kres-uyum-haftasi' => ['uyum-ve-gelisim', 'Kreşe Uyum Haftası Nasıl Geçer?', 'Kreşe yeni başlayan çocuklar için uyum haftası nasıl planlanır? Kademeli başlangıç, vedalaşma, evde hazırlık ve ilk günlerde ebeveynlere öneriler.'],
        'cocuk-kreste-ayrilik-kaygisi' => ['uyum-ve-gelisim', 'Kreşte Ayrılık Kaygısı: Çocuğunuza Nasıl Destek Olursunuz?', 'Ayrılık kaygısı nedir, hangi yaşlarda görülür, kreşe başlayan çocukta nasıl kendini gösterir ve ebeveynler bu dönemde nasıl destek olabilir?'],
        'cocuk-kres-kapisinda-aglama' => ['uyum-ve-gelisim', 'Kreş Kapısında Ağlayan Çocuk: Ne Yapmalı?', 'Kreşe bırakırken ağlayan çocuğa nasıl yaklaşılmalı? Sabah rutinleri, kısa vedalaşma, öğretmenle iş birliği ve ebeveynin kendi duygularıyla başa çıkması.'],
        'cocuk-dil-gelisimi-0-6-yas' => ['uyum-ve-gelisim', '0-6 Yaş Dil Gelişimi: Ebeveynler Neye Dikkat Etmeli?', 'Okul öncesi dönemde dil gelişimi nasıl ilerler? Evde ve kreşte dil gelişimini destekleyen yollar ve uzmana danışmanın uygun olabileceği durumlar.'],
        'cocuk-ince-motor-gelisim' => ['uyum-ve-gelisim', 'İnce Motor Becerileri: Evde ve Kreşte Nasıl Desteklenir?', 'Kalem tutma, makas kullanma, düğme ilikleme gibi ince motor becerilerinin önemi, yaşa göre gelişimi ve evde yapılabilecek basit etkinlikler.'],
        'cocuk-kaba-motor-gelisim' => ['uyum-ve-gelisim', 'Kaba Motor Gelişim: Koşmak, Zıplamak, Tırmanmak', 'Kaba motor becerilerin çocuk gelişimindeki yeri, yaşa göre genel gelişim, hareketi destekleyen oyunlar ve kreşte hareket imkânlarının önemi.'],
        'cocuk-paylasmayi-ogrenmek' => ['uyum-ve-gelisim', 'Çocuklar Paylaşmayı Nasıl Öğrenir?', 'Okul öncesi çocuklarda paylaşma neden zor olabilir, hangi yaşta gelişir? Ebeveynlerin ve kreşin paylaşma becerisini desteklemek için yapabilecekleri.'],
        'cocuk-tuvalet-egitimi-ve-kres' => ['uyum-ve-gelisim', 'Tuvalet Eğitimi ve Kreş: Ebeveynlere Öneriler', 'Tuvalet eğitimine hazır olma işaretleri, kreşle iş birliği, kazalar karşısında doğru tutum ve kreşe başlarken tuvalet eğitimiyle ilgili bilinmesi gerekenler.'],
        'cocuk-kreste-isirma' => ['uyum-ve-gelisim', 'Kreşte Isırma Davranışı: Nedenleri ve Yaklaşım', 'Küçük çocuklarda ısırma neden görülür, kreşte ısırma olayları nasıl yönetilir? Isıran ve ısırılan çocuğun ebeveynlerine öneriler.'],
        'cocuk-iki-yas-donemi' => ['uyum-ve-gelisim', 'İki Yaş Dönemi: "Hayır" Çağında Ebeveynlik', 'İki yaş döneminde çocukların bağımsızlık isteği, inatlaşma, öfke patlamaları ve bu döneme uygun ebeveyn yaklaşımları hakkında öneriler.'],
        'cocuk-kreste-arkadaslik' => ['uyum-ve-gelisim', 'Kreşte Arkadaşlık: Çocuğunuzun Sosyal Gelişimini Desteklemek', 'Okul öncesi çocuklarda arkadaşlık nasıl gelişir? Arkadaş edinmekte zorlanan çocuklar, arkadaşlık sorunları ve ebeveynlerin destek yolları.'],
        'cocuk-okula-hazirlik-becerileri' => ['uyum-ve-gelisim', 'Okula Hazırlık Becerileri: İlkokuldan Önce Neler Önemli?', 'İlkokula hazırlıkta akademik bilgiden çok öz bakım, dikkat, sosyal-duygusal beceriler ve dil becerileri önemlidir. Evde ve anaokulunda destekleme önerileri.'],
        'cocuk-utangac-cocuk-ve-kres' => ['uyum-ve-gelisim', 'Utangaç Çocuk ve Kreş: Nasıl Destek Olunur?', 'Utangaç ve çekingen çocukların kreşe uyumu nasıl desteklenir? Mizaca saygı, küçük adımlar, öğretmenle iş birliği ve kaçınılması gereken davranışlar.'],
        'cocuk-kres-gelisim-raporu' => ['uyum-ve-gelisim', 'Kreş Gelişim Raporu Nasıl Okunur?', 'Kreş ve anaokullarında verilen gelişim raporları neyi gösterir? Gelişim alanları, rapordaki ifadeleri anlamak, öğretmenle görüşme ve evde destek önerileri.'],
        'cocuk-okul-oncesi-ekran-suresi' => ['uyum-ve-gelisim', 'Okul Öncesinde Ekran Süresi: Ebeveynlere Öneriler', 'Okul öncesi çocuklarda ekran kullanımının gelişime etkisi, sağlıklı ekran alışkanlıkları, içerik seçimi ve ekransız zamanlar için öneriler.'],
        'cocuk-kardes-dogumu-ve-kres' => ['uyum-ve-gelisim', 'Kardeş Doğumu ve Kreş Uyumu', 'Yeni bir kardeşin doğumu kreşe giden çocuğu nasıl etkiler? Doğum öncesi hazırlık, kreşle iş birliği ve kıskançlık tepkilerine yaklaşım önerileri.'],
        'cocuk-kreste-ogle-uykusu' => ['uyum-ve-gelisim', 'Kreşte Öğle Uykusu ve Uyku Düzeni', 'Kreşte öğle uykusu nasıl düzenlenir? Uyumak istemeyen çocuklar, evdeki uyku düzeniyle uyum, uyku ortamı ve kreşe sorulacak sorular.'],
        'cocuk-kreste-beslenme' => ['beslenme-ve-gunluk-bakim', 'Kreşte Beslenme: Ebeveynlerin Bilmesi Gerekenler', 'Kreşte çocuğunuzun beslenmesi nasıl takip edilir? Öğün düzeni, yeni yiyeceklerle tanışma, yemek yemeyen çocuklar ve evle uyum için öneriler.'],
        'cocuk-yemek-secen-cocuk' => ['beslenme-ve-gunluk-bakim', 'Yemek Seçen Çocuk: Ebeveynlere Pratik Öneriler', 'Okul öncesi dönemde yemek seçme neden sık görülür? Baskı kurmadan yeni yiyecekleri tanıtmak, sofra düzeni ve ne zaman doktora danışılacağı.'],
        'cocuk-kres-cantasi' => ['beslenme-ve-gunluk-bakim', 'Kreş Çantasında Neler Olmalı?', 'Kreşe başlayan çocuklar için çanta hazırlama listesi: yedek kıyafet, kişisel bakım malzemeleri, uyku eşyaları, etiketleme ve mevsime göre ekler.'],
        'cocuk-kreste-sik-hastalanma' => ['beslenme-ve-gunluk-bakim', 'Kreşe Başlayınca Sık Hastalanma: Ebeveynlere Bilgiler', 'Kreşe başlayan çocukların neden sık hastalanabildiği, hastalıkların yayılmasını azaltmak için alınabilecek önlemler ve doktora danışılması gereken durumlar.'],
        'cocuk-hasta-cocuk-krese-gider-mi' => ['beslenme-ve-gunluk-bakim', 'Hasta Çocuk Kreşe Gider mi?', 'Çocuğunuz hastalandığında kreşe gönderip göndermeme kararı nasıl verilir? Genel ölçütler, kreş kuralları, iyileşme sonrası dönüş ve diğer çocukların sağlığı.'],
        'cocuk-besin-alerjisi-kres' => ['beslenme-ve-gunluk-bakim', 'Besin Alerjisi Olan Çocuk ve Kreş', 'Besin alerjisi olan çocuğunuzu kreşe başlatırken kreşle bilgi paylaşımı, mutfak ve sınıf önlemleri, acil durum planı ve özel günlerde dikkat edilecekler.'],
        'cocuk-kreste-ilac-verilmesi' => ['beslenme-ve-gunluk-bakim', 'Kreşte İlaç Verilmesi: Velilerin Bilmesi Gerekenler', 'Çocuğunuzun kreşte ilaç alması gerektiğinde izlenecek adımlar: kreşin kuralları, yazılı talimat, doz ve saat bilgisi, saklama koşulları ve sürekli ilaç kullanan çocuklar.'],
        'cocuk-el-yikama-aliskanligi' => ['beslenme-ve-gunluk-bakim', 'Çocuklarda El Yıkama Alışkanlığı Nasıl Kazandırılır?', 'Okul öncesi çocuklara el yıkama alışkanlığını kazandırmanın yolları: ne zaman yıkanmalı, doğru teknik, eğlenceli yöntemler, model olma ve kreşle iş birliği.'],
        'cocuk-kres-kiyafetleri' => ['beslenme-ve-gunluk-bakim', 'Kreş İçin Kıyafet Seçimi', 'Kreşe giden çocuklar için rahat, güvenli ve bağımsızlığı destekleyen kıyafet seçimi; ayakkabı, mevsime göre giyim, etiketleme ve kaçınılması gereken detaylar.'],
        'cocuk-kres-sabah-rutini' => ['beslenme-ve-gunluk-bakim', 'Kreş Sabahları İçin Kolay Bir Rutin', 'Kreş sabahlarını telaşsız geçirmek için akşamdan hazırlık, uyanma, kahvaltı, giyinme ve evden çıkış adımları; görsel çizelge ve ağlama anları için öneriler.'],
        'cocuk-ara-ogun-fikirleri' => ['beslenme-ve-gunluk-bakim', 'Okul Öncesi Çocuklar İçin Sağlıklı Ara Öğün Fikirleri', 'Kreşten sonra ya da öğünler arasında okul öncesi çocuklara sunulabilecek sağlıklı ara öğün önerileri, porsiyon ve zamanlama, paketli ürünler ve çocuğu hazırlığa katmak.'],
        'cocuk-su-icme-aliskanligi' => ['beslenme-ve-gunluk-bakim', 'Çocuklarda Su İçme Alışkanlığı', 'Okul öncesi çocuklarda yeterli su içmenin önemi, su içmeyi teşvik etmenin yolları, sıcak havalarda ve hastalık dönemlerinde dikkat edilecekler, kreşle iş birliği.'],
        'cocuk-kres-sonrasi-aksam-rutini' => ['beslenme-ve-gunluk-bakim', 'Kreş Sonrası Akşam Rutini', 'Kreşten dönen çocuklar için dinlenme, ara öğün, aile zamanı, akşam yemeği ve uyku hazırlığından oluşan sakin bir akşam rutini önerisi.'],
        'cocuk-dis-fircalama-aliskanligi' => ['beslenme-ve-gunluk-bakim', 'Okul Öncesinde Diş Fırçalama Alışkanlığı', 'Küçük çocuklara diş fırçalama alışkanlığı kazandırmanın yolları: ne zaman başlanmalı, ebeveyn desteği, eğlenceli yöntemler, beslenme ve diş hekimi kontrolleri.'],
        'cocuk-yaz-aylarinda-kres' => ['beslenme-ve-gunluk-bakim', 'Yaz Aylarında Kreş ve Yaz Okulu', 'Yaz aylarında kreşe devam etmek mi, yaz okuluna gitmek mi? Sıcak havada güvenlik, güneş koruması, su etkinlikleri ve tatil sonrası kreşe dönüş önerileri.'],
        'cocuk-kres-kaydi-ve-asi-karti' => ['beslenme-ve-gunluk-bakim', 'Kreş Kaydında Sağlık Belgeleri ve Aşı Kartı', 'Kreş kaydında istenebilecek sağlık belgeleri, aşı kartının önemi, sağlık bilgilerini kreşle paylaşma ve bilgilerin güncel tutulması hakkında bilgiler.'],
        'cocuk-oyunun-onemi' => ['oyun-ve-etkinlik', 'Oyun Çocuk İçin Neden Bu Kadar Önemli?', 'Okul öncesi dönemde oyunun bilişsel, sosyal, duygusal ve fiziksel gelişime katkıları; serbest oyun, ebeveynin rolü ve kreş seçiminde oyuna verilen yer.'],
        'cocuk-evde-sanat-etkinlikleri' => ['oyun-ve-etkinlik', 'Evde Sanat Etkinlikleri: Okul Öncesi Çocuklar İçin Fikirler', 'Evde kolayca yapılabilecek boyama, kolaj, baskı ve hamur etkinlikleri; malzeme seçimi, düzen ve süreç odaklı yaklaşım hakkında ebeveynlere öneriler.'],
        'cocuk-kitap-sevgisi' => ['oyun-ve-etkinlik', 'Okul Öncesinde Kitap Sevgisi Nasıl Kazandırılır?', 'Küçük çocuklara kitap sevgisi kazandırmanın yolları: yaşa uygun kitap seçimi, birlikte okuma, evde kitap köşesi, kütüphane ziyaretleri ve sesli okuma ipuçları.'],
        'cocuk-acik-hava-oyunlari' => ['oyun-ve-etkinlik', 'Açık Hava Oyunları: Okul Öncesi Çocuklar İçin Öneriler', 'Açık havada oynamanın çocuk gelişimine faydaları, parkta ve bahçede oynanabilecek oyunlar, mevsimlere göre öneriler ve güvenlik konuları.'],
        'cocuk-yasa-uygun-oyuncak' => ['oyun-ve-etkinlik', 'Yaşa Uygun Oyuncak Seçimi', 'Okul öncesi çocuklar için oyuncak seçerken yaş, gelişim, güvenlik ve oyun değeri açısından dikkat edilecekler; az ama işlevsel oyuncak yaklaşımı.'],
        'cocuk-muzik-ve-ritim' => ['oyun-ve-etkinlik', 'Okul Öncesinde Müzik ve Ritim Etkinlikleri', 'Müziğin okul öncesi çocukların gelişimine katkıları, evde yapılabilecek şarkı, dans ve ritim etkinlikleri, basit çalgılar ve müziği günlük rutine katmak.'],
        'cocuk-rol-oyunlari' => ['oyun-ve-etkinlik', 'Rol Oyunlarının Çocuk Gelişimine Faydaları', 'Evcilik, doktorculuk, market gibi rol oyunlarının dil, sosyal ve duygusal gelişime katkıları; evde rol oyunu köşesi ve ebeveynin oyuna katılımı.'],
        'cocuk-yagmurlu-gun-etkinlikleri' => ['oyun-ve-etkinlik', 'Yağmurlu Günler İçin Ev Etkinlikleri', 'Dışarı çıkılamayan günlerde okul öncesi çocuklarla evde yapılabilecek hareket, sanat, yapı ve sakin etkinlikler; ekran dışı eğlenceli fikirler.'],
        'cocuk-doga-etkinlikleri' => ['oyun-ve-etkinlik', 'Okul Öncesi Çocuklar İçin Doğa Etkinlikleri', 'Doğada vakit geçirmenin çocuklara faydaları; yürüyüş, gözlem, toplama, bitki yetiştirme gibi etkinlikler ve doğaya saygı ile güvenlik konuları.'],
        'cocuk-mutfakta-etkinlik' => ['oyun-ve-etkinlik', 'Mutfakta Çocukla Etkinlik: Öğrenerek Eğlenmek', 'Okul öncesi çocukların mutfakta yapabileceği güvenli görevler, mutfak etkinliklerinin gelişime katkıları, basit tarif fikirleri ve güvenlik kuralları.'],
        'cocuk-sayilarla-oyunlar' => ['oyun-ve-etkinlik', 'Sayılarla Oyunlar: Okul Öncesinde Matematik Sevgisi', 'Okul öncesi çocuklarda sayı kavramını oyunla destekleme: günlük hayatta sayma, eşleştirme, sıralama ve basit oyunlar; baskı kurmadan matematik sevgisi kazandırmak.'],
        'cocuk-renk-ve-sekil-oyunlari' => ['oyun-ve-etkinlik', 'Renk ve Şekil Öğreten Oyunlar', 'Okul öncesi çocuklara renkleri ve şekilleri oyunla öğretmenin yolları: günlük hayatta keşif, sanat etkinlikleri, eşleştirme oyunları ve doğadan örnekler.'],
        'cocuk-masal-anlatmak' => ['oyun-ve-etkinlik', 'Masal Anlatmanın Çocuklara Faydaları', 'Masal ve hikâye anlatmanın dil, hayal gücü, duygusal gelişim ve aile bağına katkıları; etkili masal anlatma ipuçları ve çocuğu hikâyeye katmak.'],
        'cocuk-kres-etkinlikleri-veli-katilimi' => ['oyun-ve-etkinlik', 'Kreş Etkinlikleri ve Veli Katılımı', 'Kreşlerde düzenlenen veli katılımlı etkinlikler, ailenin kreş hayatına katılımının çocuğa faydaları, çalışan ebeveynler için öneriler ve katılım yolları.'],
        'cocuk-kreste-dogum-gunu' => ['oyun-ve-etkinlik', 'Kreşte Doğum Günü Kutlamaları', 'Kreşte doğum günü kutlaması planlarken kreşin kuralları, sağlıklı ikramlar, alerji duyarlılığı, sade ve kapsayıcı kutlama önerileri.'],
        'cocuk-hafta-sonu-aile-aktiviteleri' => ['oyun-ve-etkinlik', 'Hafta Sonu Aile Aktiviteleri: Okul Öncesi Çocuklar İçin Öneriler', 'Kreşe giden çocuklarla hafta sonlarını dinlendirici ve keyifli geçirmek için açık hava, kültür, ev içi etkinlik önerileri ve dinlenme dengesi.'],
        'cocuk-calisan-anne-ve-kres' => ['ebeveynlik', 'Çalışan Anne ve Kreş Kararı', 'İşe dönen anneler için kreş kararı: doğru zamanlama, uyum süreci, suçluluk duygusuyla başa çıkma, aile içi destek ve iş-aile dengesi önerileri.'],
        'cocuk-sinir-koymak' => ['ebeveynlik', 'Okul Öncesinde Sınır Koymak', 'Küçük çocuklara sevgiyle ve tutarlı şekilde sınır koymanın yolları: net kurallar, seçenek sunma, sonuçlar, ebeveynler arası uyum ve kreşle tutarlılık.'],
        'cocuk-ofke-nobetleri' => ['ebeveynlik', 'Okul Öncesi Çocuklarda Öfke Nöbetleri', 'Küçük çocuklarda öfke nöbetlerinin nedenleri, nöbet anında ve sonrasında ebeveyn tutumu, tetikleyicileri azaltma yolları ve ne zaman uzmana danışılmalı.'],
        'cocuk-olumlu-disiplin' => ['ebeveynlik', 'Olumlu Disiplin Nedir?', 'Olumlu disiplin yaklaşımının temel ilkeleri, ceza yerine öğretmeye odaklanmak, iyi davranışı fark etmek, sorun çözme ve okul öncesi çocuklarla günlük uygulamalar.'],
        'cocuk-ogretmenle-iletisim' => ['ebeveynlik', 'Kreş Öğretmeniyle İletişim: Güçlü Bir İş Birliği İçin', 'Kreş öğretmeniyle sağlıklı iletişim kurmanın yolları: günlük bilgi paylaşımı, doğru zaman ve kanal, endişeleri iletmek ve olumlu geri bildirim vermek.'],
        'cocuk-veli-toplantisi' => ['ebeveynlik', 'Kreş Veli Toplantısına Hazırlık', 'Kreş ve anaokulu veli toplantılarından en iyi şekilde yararlanmak için toplantı öncesi hazırlık, sorulacak sorular, dinleme ve sonrasında yapılacaklar.'],
        'cocuk-mahremiyet-egitimi' => ['ebeveynlik', 'Okul Öncesinde Mahremiyet Eğitimi', 'Küçük çocuklara beden mahremiyetini yaşlarına uygun şekilde öğretmenin yolları: doğru isimler, özel bölgeler, "hayır" deme, sırlar ve güvendiği yetişkinler.'],
        'cocuk-buyukanne-mi-kres-mi' => ['ebeveynlik', 'Büyükanne mi, Kreş mi?', 'Çalışan ebeveynler için çocuğun bakımında büyükanne-büyükbaba ve kreş seçeneklerinin karşılaştırması; avantajlar, dikkat edilecekler ve karma çözümler.'],
        'cocuk-bakici-mi-kres-mi' => ['ebeveynlik', 'Bakıcı mı, Kreş mi?', 'Çocuğun bakımında evde bakıcı ile kreş arasında seçim yaparken bireysel ilgi, sosyalleşme, maliyet, güven, esneklik ve çocuğun yaşı açısından karşılaştırma.'],
        'cocuk-babanin-katilimi' => ['ebeveynlik', 'Babanın Kreş Sürecine Katılımı', 'Babaların kreş sürecine ve okul öncesi dönemde çocuk bakımına aktif katılımının çocuğa, aileye ve babaya faydaları; pratik katılım önerileri.'],
        'cocuk-okul-oncesi-ozguven' => ['ebeveynlik', 'Okul Öncesinde Özgüven Nasıl Desteklenir?', 'Okul öncesi çocuklarda sağlıklı özgüvenin temelleri: bağımsızlığa fırsat, çabayı takdir, hatalara yaklaşım, karşılaştırmadan kaçınma ve koşulsuz sevgi.'],
        'cocuk-kucuk-sorumluluklar' => ['ebeveynlik', 'Okul Öncesi Çocuklara Küçük Sorumluluklar', 'Okul öncesi çocuklara yaşa uygun sorumluluklar vermenin faydaları, örnek görevler, sorumluluğu alışkanlığa dönüştürmek ve mükemmellik beklememek.'],
        'cocuk-hayal-mi-yalan-mi' => ['ebeveynlik', 'Hayal mi, Yalan mı? Okul Öncesinde Gerçek ile Hayal', 'Okul öncesi çocukların hayal ile gerçeği karıştırması, hayali arkadaşlar, gerçek dışı anlatımlar, yalanın gelişimsel boyutu ve ebeveyn tutumu.'],
        'cocuk-cocukluk-korkulari' => ['ebeveynlik', 'Okul Öncesinde Çocukluk Korkuları', 'Karanlık, canavar, yalnız kalma ve yüksek ses gibi okul öncesi korkuların nedenleri, korkuyla başa çıkmada ebeveyn tutumu ve ne zaman destek alınmalı.'],
        'cocuk-bosanma-surecinde-kres' => ['ebeveynlik', 'Boşanma Sürecinde Kreşteki Çocuk', 'Ebeveynlerin ayrılık ya da boşanma sürecinde kreşe giden çocuğu desteklemek: kreşle bilgi paylaşımı, rutin, teslim kuralları, çocuğun duyguları ve iş birliği.'],
        'cocuk-ebeveynin-ayrilik-kaygisi' => ['ebeveynlik', 'Ebeveynin Ayrılık Kaygısı: Çocuğu Kreşe Bırakırken', 'Çocuğunu kreşe bırakırken ebeveynin yaşadığı kaygının nedenleri, çocuğa yansımaması için öneriler, kreşe güven duymak ve bu duygularla başa çıkma yolları.'],
        'cocuk-kreste-sorun-yasaninca' => ['ebeveynlik', 'Kreşte Sorun Yaşandığında Ne Yapmalı?', 'Kreşte bir kaza, anlaşmazlık ya da endişe verici bir durum yaşandığında izlenecek adımlar: bilgi toplamak, öğretmen ve yönetimle görüşmek, kayıt tutmak ve resmî başvuru.'],
        'cocuk-kres-kayit-belgeleri' => ['kayit-ve-ucretler', 'Kreş Kaydı İçin Gerekli Belgeler', 'Kreş ve anaokulu kaydında genellikle istenen belgeler, sağlık belgeleri, veli bilgileri, kayıt öncesi hazırlık listesi ve dikkat edilmesi gerekenler.'],
        'cocuk-kres-sozlesmesi' => ['kayit-ve-ucretler', 'Kreş Sözleşmesinde Nelere Dikkat Edilmeli?', 'Kreş sözleşmesi imzalamadan önce kontrol edilmesi gereken maddeler: ücret ve kapsamı, ödeme koşulları, tatiller, iptal ve iade, sorumluluklar ve iletişim.'],
        'cocuk-kres-kayit-donemi' => ['kayit-ve-ucretler', 'Kreş Kayıtları Ne Zaman Yapılır?', 'Kreş ve anaokulu kayıt dönemleri, erken araştırmanın önemi, yıl içinde kayıt, kontenjan durumu ve kayıt takvimini planlama önerileri.'],
        'cocuk-kres-ucretine-dahil-olanlar' => ['kayit-ve-ucretler', 'Kreş Ücretine Neler Dahil?', 'Kreş ücretini değerlendirirken eğitim, yemek, materyal, etkinlik, servis ve diğer kalemlerin ücrete dahil olup olmadığını öğrenmek; kreşleri doğru karşılaştırmak.'],
        'cocuk-kres-indirimleri' => ['kayit-ve-ucretler', 'Kreşlerde Kardeş ve Erken Kayıt İndirimleri', 'Kreş ve anaokullarında uygulanabilen kardeş, erken kayıt, peşin ödeme ve kurum indirimleri hakkında bilgiler; indirimleri değerlendirirken dikkat edilecekler.'],
        'cocuk-devlet-anaokulu-mu-ozel-kres-mi' => ['kayit-ve-ucretler', 'Devlet Anaokulu mu, Özel Kreş mi?', 'Devlet anaokulları ile özel kreşler arasındaki farklar: yaş grupları, saatler, sınıf mevcudu, maliyet, kontenjan ve aile ihtiyaçlarına göre seçim önerileri.'],
        'cocuk-calisan-annelere-kres-destegi' => ['kayit-ve-ucretler', 'Çalışan Annelere Kreş Desteği', 'Çalışan annelere yönelik kreş desteği uygulamalarının genel çerçevesi, işveren kreşleri, başvuru için bilgi kaynakları ve dikkat edilmesi gerekenler.'],
        'cocuk-kres-ucret-artislari' => ['kayit-ve-ucretler', 'Kreş Ücret Artışları: Velilerin Bilmesi Gerekenler', 'Kreş ücretlerinin neden ve ne zaman artabileceği, sözleşmede artış maddesi, dönem ortası zamlar, veliler için sorulacak sorular ve bütçe planlaması.'],
        'cocuk-kres-iade-kosullari' => ['kayit-ve-ucretler', 'Kreş Ücret İadesi ve Ayrılma Koşulları', 'Kreşten ayrılırken ücret iadesi, kayıt ücreti, peşin ödemeler, bildirim süresi, sağlık nedeniyle ayrılma ve sözleşmede dikkat edilecek maddeler.'],
        'cocuk-kres-bekleme-listesi' => ['kayit-ve-ucretler', 'Kreş Bekleme Listesi: Nasıl Hareket Etmeli?', 'Talebin yüksek olduğu kreşlerde bekleme listesine girmek, ön kayıt, öncelik kriterleri, takip, alternatif planlar ve bekleme sürecinde çocuğun bakımı.'],
        'cocuk-kres-butcesi' => ['kayit-ve-ucretler', 'Kreş Bütçesi Nasıl Planlanır?', 'Kreş giderlerini planlamak: aylık ücret dışındaki kalemler, yıllık toplam maliyet, ödeme seçenekleri, indirim ve destekler, sürpriz giderler için pay ayırma.'],
        'cocuk-belediye-kresleri' => ['kayit-ve-ucretler', 'Belediye Kreşleri ve Gündüz Bakımevleri', 'Belediyelerin işlettiği kreş ve gündüz bakımevleri hakkında genel bilgi: başvuru, kontenjan, ücret yapısı, öncelik kriterleri ve özel kreşlerle karşılaştırma.'],
        'cocuk-kres-ruhsati' => ['kayit-ve-ucretler', 'Kreş Ruhsatı Neden Önemli? Nasıl Kontrol Edilir?', 'Kreş ve anaokullarında izin ve ruhsatın önemi, bağlı olunan bakanlık, ruhsatın nasıl sorulacağı, kontrol edilecek belgeler ve ruhsatsız kurumların riskleri.'],
        'cocuk-anaokulundan-ilkokula-gecis' => ['kayit-ve-ucretler', 'Anaokulundan İlkokula Geçiş: Kayıt ve Uyum', 'Anaokulundan ilkokula geçişte kayıt süreci, okula hazır olma, ailenin hazırlık adımları, ilk günler, öğretmenle iletişim ve okul sonrası bakım planı.'],
        'cocuk-kreste-yas-gruplari' => ['kayit-ve-ucretler', 'Kreşte Yaş Grupları ve Sınıf Düzeni', 'Kreş ve anaokullarında yaş gruplarının nasıl oluşturulduğu, her yaş grubunun ihtiyaçları, karma yaş sınıfları, sınıf geçişleri ve kayıt sırasında sorulacak sorular.'],
        'cocuk-yaz-okulu-secimi' => ['kayit-ve-ucretler', 'Yaz Okulu Seçimi: Nelere Dikkat Etmeli?', 'Okul öncesi ve ilkokul çağındaki çocuklar için yaz okulu seçerken program içeriği, güvenlik, öğretmenler, açık hava etkinlikleri, saatler, ücret kalemleri ve çocuğun ilgisi.'],
        'cocuk-kres-tekliflerini-karsilastirmak' => ['kayit-ve-ucretler', 'Kreş Tekliflerini Karşılaştırmak: Doğru Seçim İçin Rehber', 'Birden fazla kreşten alınan teklifleri karşılaştırmak: toplam maliyet, ücrete dahil hizmetler, eğitim programı, öğretmen oranı, konum, sözleşme koşulları ve karar tablosu.'],
    ],
    'bakimeviara' => [
        'rehabilitasyon-fizik-tedavi-ilk-seans' => ['rehabilitasyon-sureci', 'Fizik Tedavide İlk Seans: Neler Beklenmeli?', 'Fizik tedaviye ilk kez başlayacaklar için ilk değerlendirme, hedef belirleme, seansa hazırlık ve terapistle iletişim hakkında bilinmesi gerekenler.'],
        'rehabilitasyon-hedefleri-nasil-belirlenir' => ['rehabilitasyon-sureci', 'Rehabilitasyonda Hedefler Nasıl Belirlenir?', 'Rehabilitasyon sürecinde gerçekçi ve ölçülebilir hedefler nasıl konulur? Kısa ve uzun vadeli hedefler, aile katılımı ve hedeflerin güncellenmesi.'],
        'rehabilitasyon-ev-egzersiz-programi' => ['rehabilitasyon-sureci', 'Ev Egzersiz Programına Uyum Nasıl Sağlanır?', 'Fizik tedavide verilen ev egzersizlerini düzenli yapmanın yolları: rutin oluşturma, güvenlik, motivasyon ve ailenin desteği.'],
        'rehabilitasyon-ne-kadar-surer' => ['rehabilitasyon-sureci', 'Rehabilitasyon Ne Kadar Sürer?', 'Rehabilitasyon sürecinin süresini belirleyen etkenler, ilerlemenin nasıl değerlendirildiği ve sürecin sonunda neler olduğu hakkında aileler için bilgiler.'],
        'rehabilitasyon-ergoterapi-nedir' => ['rehabilitasyon-sureci', 'Ergoterapi Nedir, Kimler İçin Gerekir?', 'Ergoterapinin amacı, fizyoterapiden farkı, kimlere uygulandığı ve günlük yaşam becerilerine nasıl katkı sağladığı hakkında aileler için temel bilgiler.'],
        'rehabilitasyon-dil-ve-konusma-terapisi' => ['rehabilitasyon-sureci', 'Dil ve Konuşma Terapisi Nedir?', 'Dil ve konuşma terapisinin hangi alanlarda destek sağladığı, çocuklarda ve yetişkinlerde kimlere uygulandığı ve aileler için süreç hakkında bilgiler.'],
        'rehabilitasyon-motivasyon' => ['rehabilitasyon-sureci', 'Rehabilitasyonda Motivasyonu Korumak', 'Uzun süren rehabilitasyon sürecinde motivasyon nasıl korunur? Küçük başarıları görmek, rutin, sosyal destek ve zor dönemlerle başa çıkma önerileri.'],
        'rehabilitasyon-yardimci-cihazlar' => ['rehabilitasyon-sureci', 'Rehabilitasyonda Yardımcı Cihazlar: Yürüteç, Baston ve Ortez', 'Yürüteç, baston, koltuk değneği ve ortez gibi yardımcı cihazlar ne işe yarar, nasıl seçilir? Doğru kullanım ve güvenlik için temel bilgiler.'],
        'rehabilitasyon-hidroterapi-nedir' => ['rehabilitasyon-sureci', 'Hidroterapi (Su İçi Egzersiz) Nedir?', 'Su içi egzersizlerin rehabilitasyondaki yeri, kimler için uygun olabileceği, dikkat edilmesi gerekenler ve merkez seçerken sorulacak sorular.'],
        'rehabilitasyon-sonrasi-gunluk-hayata-donus' => ['rehabilitasyon-sureci', 'Rehabilitasyon Sonrası Günlük Hayata Dönüş', 'Rehabilitasyon programı bittikten sonra kazanımları korumak, işe ve sosyal hayata dönmek, evde düzenli hareketi sürdürmek için öneriler.'],
        'rehabilitasyon-inme-sonrasi-evde-destek' => ['rehabilitasyon-sureci', 'İnme Sonrası Evde Destek: Aileler İçin Rehber', 'İnme geçiren bir yakın eve döndüğünde ev düzeni, günlük bakım, iletişim, egzersiz programı ve bakım verenin kendi sağlığı için pratik öneriler.'],
        'rehabilitasyon-kalca-protezi-sonrasi' => ['rehabilitasyon-sureci', 'Kalça Protezi Sonrası Evde Dikkat Edilecekler', 'Kalça protezi ameliyatı sonrası eve dönüşte ev düzeni, günlük hareketler, yardımcı araçlar ve rehabilitasyon süreci hakkında aileler için genel bilgiler.'],
        'rehabilitasyon-diz-protezi-sonrasi' => ['rehabilitasyon-sureci', 'Diz Protezi Sonrası Rehabilitasyon Süreci', 'Diz protezi ameliyatı sonrası rehabilitasyonun önemi, evde egzersiz, ağrı yönetimi, günlük yaşama dönüş ve dikkat edilmesi gereken işaretler.'],
        'rehabilitasyon-fizyoterapistle-iletisim' => ['rehabilitasyon-sureci', 'Fizyoterapistle İyi İletişim Nasıl Kurulur?', 'Rehabilitasyon sürecinde fizyoterapistle açık iletişim neden önemlidir? Seans öncesi hazırlık, soru sorma, geri bildirim ve aile katılımı için öneriler.'],
        'rehabilitasyon-robotik-rehabilitasyon' => ['rehabilitasyon-sureci', 'Robotik Rehabilitasyon Nedir?', 'Robotik rehabilitasyon cihazları nasıl çalışır, hangi durumlarda kullanılabilir, avantajları ve sınırlılıkları nelerdir? Merkez seçerken sorulacak sorular.'],
        'rehabilitasyon-agri-ve-beklentiler' => ['rehabilitasyon-sureci', 'Rehabilitasyonda Ağrı ve Gerçekçi Beklentiler', 'Rehabilitasyon sürecinde ağrı neden olabilir, hangi durumlar terapiste bildirilmeli? İlerleme hızına dair gerçekçi beklentiler ve sabırla ilgili öneriler.'],
        'rehabilitasyon-denge-ve-dusme-onleme' => ['rehabilitasyon-sureci', 'Denge Egzersizleri ve Düşmeleri Önlemek', 'Denge sorunlarının günlük yaşama etkisi, rehabilitasyonda denge çalışmaları, evde güvenlik önlemleri ve düşme sonrası yapılması gerekenler.'],
        'rehabilitasyon-ozel-egitim-nedir' => ['ozel-egitim', 'Özel Eğitim Nedir, Kimler Yararlanabilir?', 'Özel eğitimin amacı, özel eğitim ihtiyacının nasıl belirlendiği, okul ve rehabilitasyon merkezlerinde sunulan hizmetler ve ailelerin süreçteki rolü.'],
        'rehabilitasyon-bep-nedir' => ['ozel-egitim', 'BEP (Bireyselleştirilmiş Eğitim Programı) Nedir?', 'Bireyselleştirilmiş eğitim programının amacı, hazırlanma süreci, içeriği, ailenin katılımı ve programın değerlendirilmesi hakkında aileler için bilgiler.'],
        'rehabilitasyon-kaynastirma-egitimi' => ['ozel-egitim', 'Kaynaştırma Eğitimi: Aileler İçin Rehber', 'Kaynaştırma eğitimi nedir, nasıl uygulanır, çocuğun sınıfa uyumu nasıl desteklenir? Okulla iş birliği ve ailelerin dikkat etmesi gerekenler.'],
        'rehabilitasyon-ozel-egitim-sinifi' => ['ozel-egitim', 'Özel Eğitim Sınıfı Nedir?', 'Özel eğitim sınıflarının amacı, kaynaştırmadan farkı, sınıf düzeni, ailelerin karar verirken düşünmesi gerekenler ve okulla iletişim önerileri.'],
        'rehabilitasyon-otizmde-erken-destek' => ['ozel-egitim', 'Otizmde Erken Destek: Aileler İçin Yol Haritası', 'Otizm spektrumu hakkında temel bilgiler, erken desteğin önemi, değerlendirme süreci, eğitim yaklaşımları ve ailelerin günlük yaşamda yapabilecekleri.'],
        'rehabilitasyon-dil-konusma-gecikmesi' => ['ozel-egitim', 'Çocuklarda Dil ve Konuşma Gecikmesi', 'Dil ve konuşma gecikmesi nedir, hangi işaretler dikkate alınmalı, değerlendirme nasıl yapılır ve ailelerin evde yapabilecekleri nelerdir?'],
        'rehabilitasyon-ogrenme-guclugu' => ['ozel-egitim', 'Öğrenme Güçlüğü: Ailelerin Bilmesi Gerekenler', 'Özgül öğrenme güçlüğü nedir, okuma, yazma ve matematikte nasıl kendini gösterebilir? Değerlendirme, okulda destek ve evde yapılabilecekler.'],
        'rehabilitasyon-dikkat-eksikligi-ve-okul' => ['ozel-egitim', 'Dikkat Eksikliği ve Okul: Aileler İçin Öneriler', 'Dikkat eksikliği ve hiperaktivite yaşayan çocukların okul hayatında karşılaşabileceği zorluklar, öğretmenle iş birliği ve evde ödev düzeni için öneriler.'],
        'rehabilitasyon-ozel-egitim-ogretmeni-is-birligi' => ['ozel-egitim', 'Özel Eğitim Öğretmeniyle İş Birliği', 'Özel eğitim sürecinde aile ve öğretmen arasında güçlü bir iş birliği nasıl kurulur? İletişim, ortak hedefler, ev çalışmaları ve görüşmelere hazırlık.'],
        'rehabilitasyon-evde-destek-etkinlikleri' => ['ozel-egitim', 'Evde Destek Etkinlikleri: Özel Eğitimi Günlük Hayata Taşımak', 'Özel eğitim alan çocuklar için evde yapılabilecek basit etkinlikler; iletişim, günlük yaşam, motor ve dikkat becerilerini oyunla destekleme önerileri.'],
        'rehabilitasyon-oyun-temelli-ozel-egitim' => ['ozel-egitim', 'Oyun Temelli Özel Eğitim Nedir?', 'Özel eğitimde oyunun yeri, oyun temelli yaklaşımların çocuğun gelişimine katkıları ve ailelerin evde oyunla öğrenmeyi nasıl destekleyebileceği.'],
        'rehabilitasyon-gorsel-destekler' => ['ozel-egitim', 'Görsel Destekler: Resimli Kartlar ve Çizelgeler', 'Görsel desteklerin özel eğitimdeki yeri; resimli kartlar, günlük çizelgeler, adım adım görev kartları ve evde görsel destek hazırlama önerileri.'],
        'rehabilitasyon-sosyal-beceri-egitimi' => ['ozel-egitim', 'Sosyal Beceri Eğitimi: Neler Öğretilir?', 'Sosyal beceri eğitiminin amacı, çalışılan beceriler, grup ve bireysel çalışmalar, ailelerin evde ve toplum içinde destek olma yolları.'],
        'rehabilitasyon-okul-oncesi-ozel-egitim' => ['ozel-egitim', 'Okul Öncesi Dönemde Özel Eğitim', 'Okul öncesi dönemde özel eğitimin önemi, erken müdahale, kreş ve anaokulunda kaynaştırma, merkez desteği ve ailelerin bu dönemde yapabilecekleri.'],
        'rehabilitasyon-egitsel-degerlendirme-sureci' => ['ozel-egitim', 'Eğitsel Değerlendirme Süreci Nasıl İşler?', 'Özel eğitim ihtiyacı olan çocuklar için eğitsel değerlendirme sürecinin genel adımları, başvuru, hazırlık, değerlendirme günü ve sonrasında yapılacaklar.'],
        'rehabilitasyon-destek-egitim-odasi' => ['ozel-egitim', 'Destek Eğitim Odası Nedir?', 'Destek eğitim odası hizmetinin amacı, kimlerin yararlanabileceği, nasıl işlediği ve ailelerin okulla iş birliği içinde bu hizmetten nasıl yararlanabileceği.'],
        'rehabilitasyon-yetiskinlige-gecis' => ['ozel-egitim', 'Özel Gereksinimli Gençlerde Yetişkinliğe Geçiş', 'Okul sonrası dönem için planlama: mesleki beceriler, bağımsız yaşam becerileri, sosyal hayat, yasal temsil ve ailelerin önceden yapabileceği hazırlıklar.'],
        'rehabilitasyon-engelli-kimlik-karti' => ['raporlar-ve-haklar', 'Engelli Kimlik Kartı Nedir, Nasıl Alınır?', 'Engelli kimlik kartının amacı, hangi durumlarda kullanılabileceği, başvuru için genel adımlar ve kart kullanımında dikkat edilmesi gerekenler.'],
        'rehabilitasyon-engelli-arac-alimi' => ['raporlar-ve-haklar', 'Engelli Bireylerde Araç Alımı ve Vergi Avantajları', 'Engelli bireyler ve yakınları için araç alımında tanınabilen vergi avantajlarının genel çerçevesi, rapor koşulları, dikkat edilmesi gerekenler ve bilgi kaynakları.'],
        'rehabilitasyon-engelli-otopark-ve-erisilebilirlik' => ['raporlar-ve-haklar', 'Erişilebilirlik Hakları: Otopark, Bina ve Kamusal Alanlar', 'Engelli bireylerin kamusal alanlarda erişilebilirlik hakları, engelli otoparkları, binalarda erişim, erişilebilirlik sorunlarını bildirme yolları ve günlük yaşamda pratik öneriler.'],
        'rehabilitasyon-engelli-evde-bakim-destegi' => ['raporlar-ve-haklar', 'Engelli Bireyler İçin Evde Bakım Desteği', 'Bakıma muhtaç engelli bireylerin evde bakımı için sağlanan desteğin genel çerçevesi, başvuru süreci, değerlendirme ve ailelerin dikkat etmesi gerekenler.'],
        'rehabilitasyon-engelli-ogrencinin-haklari' => ['raporlar-ve-haklar', 'Engelli Öğrencinin Eğitim Hakları', 'Engelli ve özel gereksinimli öğrencilerin eğitim hakları; uygun eğitim ortamı, bireyselleştirilmiş program, sınav düzenlemeleri, ulaşım ve ailelerin başvurabileceği yollar.'],
        'rehabilitasyon-is-hayatinda-engelli-haklari' => ['raporlar-ve-haklar', 'İş Hayatında Engelli Bireylerin Hakları', 'Engelli bireylerin çalışma hayatına katılımına ilişkin genel haklar, iş arama, iş yerinde makul düzenlemeler, ayrımcılığa karşı korunma ve başvuru kaynakları.'],
        'rehabilitasyon-engelli-ulasim-karti' => ['raporlar-ve-haklar', 'Engelli Bireyler İçin Ulaşım Kolaylıkları', 'Engelli bireylerin ve refakatçilerinin toplu taşımada yararlanabileceği ulaşım kolaylıkları, şehir içi ve şehirlerarası ulaşım, başvuru adımları ve dikkat edilecekler.'],
        'rehabilitasyon-engelli-vergi-indirimi' => ['raporlar-ve-haklar', 'Engelli Bireyler ve Yakınları İçin Vergi İndirimi', 'Engelli bireyler ve bakmakla yükümlü oldukları engelli yakınları bulunan çalışanlar için vergi indiriminin genel çerçevesi, başvuru adımları ve bilgi kaynakları.'],
        'rehabilitasyon-rapor-yenileme' => ['raporlar-ve-haklar', 'Sağlık Kurulu Raporu Yenileme: Nelere Dikkat Edilmeli?', 'Süreli engelli sağlık kurulu raporlarının yenilenmesi, yenileme zamanını takip etmek, gerekli hazırlıklar ve raporun haklar üzerindeki etkisi.'],
        'rehabilitasyon-rapora-itiraz' => ['raporlar-ve-haklar', 'Sağlık Kurulu Raporuna İtiraz Nasıl Yapılır?', 'Engelli sağlık kurulu raporunun sonucuna katılmadığınızda izlenebilecek genel yol, itiraz öncesi hazırlık, belgeler ve süreç boyunca dikkat edilecekler.'],
        'rehabilitasyon-agir-engelli-ibaresi' => ['raporlar-ve-haklar', 'Raporda "Ağır Engelli" İbaresi Ne Anlama Gelir?', 'Sağlık kurulu raporlarında yer alan ağır engelli ve bakıma muhtaçlık ifadelerinin genel anlamı, bağlantılı haklar ve raporu kontrol ederken dikkat edilecekler.'],
        'rehabilitasyon-cihaz-ve-ortez-odemeleri' => ['raporlar-ve-haklar', 'Tıbbi Cihaz ve Ortez Ödemeleri Nasıl İşler?', 'Ortez, protez, tekerlekli sandalye ve diğer tıbbi cihazların teminine ilişkin genel süreç; rapor, reçete, ödeme koşulları ve dikkat edilmesi gerekenler.'],
        'rehabilitasyon-saglik-kurulu-sureci' => ['raporlar-ve-haklar', 'Engelli Sağlık Kurulu Süreci Nasıl İşler?', 'Engelli sağlık kurulu raporu almak için genel süreç: randevu, gerekli belgeler, muayene günü, değerlendirme ve rapor sonrasında yapılacaklar.'],
        'rehabilitasyon-yetiskin-engelli-vasi' => ['raporlar-ve-haklar', 'Yetişkin Engelli Bireyler ve Vasilik', 'Kendi işlerini yürütmekte desteğe ihtiyaç duyan yetişkin engelli bireyler için vasilik kavramı, ne zaman gündeme gelir, süreç ve ailelerin dikkat etmesi gerekenler.'],
        'rehabilitasyon-engelli-bireylerin-tatil-haklari' => ['raporlar-ve-haklar', 'Engelli Bireylerin Sosyal ve Kültürel Hakları', 'Engelli bireylerin müzeler, kültürel etkinlikler, spor, rekreasyon ve sosyal hayata katılımına ilişkin genel haklar ve erişilebilir etkinlik planlama önerileri.'],
        'rehabilitasyon-hak-basvurusunda-belge-dosyasi' => ['raporlar-ve-haklar', 'Hak Başvuruları İçin Belge Dosyası Hazırlamak', 'Engelli haklarına ve hizmetlere başvururken kullanılacak belgeleri düzenli bir dosyada toplamak; hangi belgeler, nasıl saklanır, dijital kopyalar ve takip listesi.'],
        'rehabilitasyon-merkez-ziyaret-kontrol-listesi' => ['merkez-secimi', 'Rehabilitasyon Merkezi Ziyaret Kontrol Listesi', 'Özel eğitim ve rehabilitasyon merkezini yerinde ziyaret ederken bakılacaklar: fiziki ortam, ekip, seans düzeni, aile iletişimi, güvenlik ve sözleşme konuları.'],
        'rehabilitasyon-ozel-egitim-ve-rehabilitasyon-merkezi' => ['merkez-secimi', 'Özel Eğitim ve Rehabilitasyon Merkezi Nedir?', 'Özel eğitim ve rehabilitasyon merkezlerinin sunduğu hizmetler, kimlerin yararlanabileceği, devlet desteğiyle ilişkisi ve okul eğitimiyle birlikte nasıl işlediği.'],
        'rehabilitasyon-fizik-tedavi-merkezi-secimi' => ['merkez-secimi', 'Fizik Tedavi Merkezi Seçerken Nelere Dikkat Edilmeli?', 'Fizik tedavi ve rehabilitasyon merkezi seçerken uzman kadro, ekipman, seans süresi, kişiye özel program, ulaşım ve maliyet açısından değerlendirme önerileri.'],
        'rehabilitasyon-terapist-niteligi' => ['merkez-secimi', 'İyi Bir Terapistte Aranacak Özellikler', 'Rehabilitasyon ve özel eğitim sürecinde terapistin eğitimi, deneyimi, iletişim becerileri, aileyle iş birliği ve gözlemlenebilecek işaretler.'],
        'rehabilitasyon-seans-suresi-ve-sikligi' => ['merkez-secimi', 'Seans Süresi ve Sıklığı Nasıl Belirlenir?', 'Rehabilitasyon ve özel eğitim seanslarının süresi ve haftalık sıklığını belirleyen etkenler, çocuğun yorgunluğu, okul ve aile düzeniyle denge.'],
        'rehabilitasyon-bireysel-mi-grup-mu' => ['merkez-secimi', 'Bireysel mi, Grup Eğitimi mi?', 'Özel eğitim ve rehabilitasyonda bireysel ve grup seanslarının avantajları, hangi durumda hangisinin uygun olabileceği ve iki yöntemin birlikte kullanılması.'],
        'rehabilitasyon-merkez-mesafesi-ve-servis' => ['merkez-secimi', 'Merkez Mesafesi ve Servis Hizmeti', 'Rehabilitasyon merkezi seçerken evden uzaklık, yol süresi, servis hizmetinin güvenliği, refakatçi düzeni ve ulaşımın seans düzenine etkisi.'],
        'rehabilitasyon-merkez-ruhsati' => ['merkez-secimi', 'Rehabilitasyon Merkezinin Ruhsatı Nasıl Kontrol Edilir?', 'Özel eğitim ve rehabilitasyon merkezlerinde ruhsatın önemi, kontrol edilebilecek belgeler, denetim, ruhsatsız hizmetin riskleri ve bilgi kaynakları.'],
        'rehabilitasyon-ilerleme-raporu' => ['merkez-secimi', 'İlerleme Raporları Nasıl Okunur?', 'Rehabilitasyon ve özel eğitim merkezlerinin hazırladığı ilerleme raporlarında neler yer alır, nasıl yorumlanır ve terapistle görüşmede neler konuşulmalı?'],
        'rehabilitasyon-merkez-degistirmek' => ['merkez-secimi', 'Rehabilitasyon Merkezini Değiştirmek Gerekir mi?', 'Merkez değiştirmeyi düşündüren durumlar, önce merkezle görüşmenin önemi, değişiklik kararı, geçiş sürecinde çocuğu desteklemek ve kayıtların aktarılması.'],
        'rehabilitasyon-yatili-rehabilitasyon' => ['merkez-secimi', 'Yatılı Rehabilitasyon: Ne Zaman Düşünülür?', 'Yatılı rehabilitasyon programlarının amacı, kimler için uygun olabileceği, avantajları, aile katılımı ve merkez seçerken dikkat edilecekler.'],
        'rehabilitasyon-gunduzlu-rehabilitasyon' => ['merkez-secimi', 'Gündüzlü Rehabilitasyon Programları', 'Gündüzlü rehabilitasyonun yatılı programlardan farkı, kimler için uygun olduğu, günlük işleyiş, avantajları ve ulaşım ile aile düzeninin planlanması.'],
        'rehabilitasyon-cocuk-dostu-merkez' => ['merkez-secimi', 'Çocuk Dostu Bir Rehabilitasyon Merkezi Nasıl Olmalı?', 'Çocuklara hizmet veren rehabilitasyon ve özel eğitim merkezlerinde fiziki ortam, oyun temelli yaklaşım, terapist tutumu, aile katılımı ve güvenlik açısından aranacak özellikler.'],
        'rehabilitasyon-ekip-yaklasimi' => ['merkez-secimi', 'Rehabilitasyonda Ekip Yaklaşımı Neden Önemli?', 'Rehabilitasyonda farklı uzmanların birlikte çalışmasının faydaları, ekipte yer alabilecek meslekler, ortak hedefler ve ailenin ekipteki yeri.'],
        'rehabilitasyon-ucretli-ek-hizmetler' => ['merkez-secimi', 'Rehabilitasyon Merkezlerinde Ücretli Ek Hizmetler', 'Devlet desteği kapsamı dışında kalabilen ek hizmetler, ücretlerin şeffaflığı, gereklilik değerlendirmesi ve ailelerin bütçe planlaması için öneriler.'],
        'rehabilitasyon-merkez-yorumlari' => ['merkez-secimi', 'Rehabilitasyon Merkezi Yorumlarını Değerlendirmek', 'İnternetteki rehabilitasyon ve özel eğitim merkezi yorumlarını okurken dikkat edilecekler: güncellik, ayrıntı, tekrarlayan şikâyetler ve yerinde doğrulama.'],
        'rehabilitasyon-ilk-gorusme-sorulari' => ['merkez-secimi', 'Rehabilitasyon Merkeziyle İlk Görüşmede Sorulacaklar', 'Özel eğitim ve rehabilitasyon merkeziyle ilk görüşmede sorulabilecek sorular: değerlendirme, program, ekip, aile katılımı, ücret ve sözleşme konuları.'],
        'rehabilitasyon-tani-sonrasi-aile' => ['aile-destegi', 'Tanı Sonrası Aile: İlk Adımlar ve Duygular', 'Çocuğuna gelişimsel bir tanı konan ailelerin yaşayabileceği duygular, ilk adımlar, bilgi edinme, destek kaynakları ve aile içi iletişim önerileri.'],
        'rehabilitasyon-kardesler' => ['aile-destegi', 'Özel Gereksinimli Çocuğun Kardeşleri', 'Özel gereksinimli bir çocuğun kardeşlerinin yaşayabileceği duygular, onlarla açık iletişim, özel zaman ayırma, sorumlulukların dengesi ve kardeş ilişkisini güçlendirme önerileri.'],
        'rehabilitasyon-ebeveyn-tukenmisligi' => ['aile-destegi', 'Ebeveyn Tükenmişliği: Özel Gereksinimli Çocuğu Olan Aileler İçin', 'Uzun soluklu bakım sürecinde ebeveyn tükenmişliğinin işaretleri, nedenleri, kendine bakım, görev paylaşımı ve profesyonel destek almanın önemi.'],
        'rehabilitasyon-aile-ici-is-bolumu' => ['aile-destegi', 'Özel Gereksinimli Çocuğun Bakımında Aile İçi İş Bölümü', 'Terapi, okul, sağlık ve günlük bakım sorumluluklarının ebeveynler ve aile üyeleri arasında adil paylaşımı; planlama, iletişim ve destek isteme önerileri.'],
        'rehabilitasyon-cevreye-anlatmak' => ['aile-destegi', 'Çocuğunuzun Durumunu Çevreye Anlatmak', 'Özel gereksinimli çocuğun durumunu akrabalara, komşulara ve arkadaşlara anlatırken nelere dikkat edilmeli? Bilgi düzeyi, dil, olumsuz tepkiler ve farkındalık.'],
        'rehabilitasyon-aile-egitim-programlari' => ['aile-destegi', 'Aile Eğitim Programları: Neler Sunar?', 'Özel gereksinimli çocukların ailelerine yönelik eğitim programlarının amacı, içeriği, katılımın faydaları ve programlara nereden ulaşılabileceği.'],
        'rehabilitasyon-destek-gruplari' => ['aile-destegi', 'Aileler İçin Destek Grupları', 'Özel gereksinimli çocuğu olan aileler için destek gruplarının faydaları, grup türleri, uygun grubu bulmak ve gruplardan en iyi şekilde yararlanma önerileri.'],
        'rehabilitasyon-babanin-katilimi' => ['aile-destegi', 'Özel Gereksinimli Çocuğun Gelişiminde Babanın Rolü', 'Özel eğitim ve rehabilitasyon sürecinde babanın aktif katılımının çocuğa ve aileye faydaları, katılım yolları ve babaların yaşayabileceği duygular.'],
        'rehabilitasyon-kucuk-ilerlemeler' => ['aile-destegi', 'Küçük İlerlemeleri Görmek ve Kutlamak', 'Rehabilitasyon ve özel eğitim sürecinde küçük ilerlemelerin önemi, ilerlemeyi fark etmenin yolları, karşılaştırmadan kaçınma ve motivasyonu korumak.'],
        'rehabilitasyon-buyukanne-buyukbaba' => ['aile-destegi', 'Büyükanne ve Büyükbabaların Desteği', 'Özel gereksinimli torunun bakımında büyükanne ve büyükbabaların rolü, onları bilgilendirmek, duyguları, beklentiler ve destek olmanın yolları.'],
        'rehabilitasyon-is-ve-bakim-dengesi' => ['aile-destegi', 'İş Hayatı ile Bakım Sorumluluğu Arasında Denge', 'Özel gereksinimli çocuğu olan çalışan ebeveynler için iş ve bakım dengesi: işverenle iletişim, esnek çalışma, yasal haklar, planlama ve destek ağı.'],
        'rehabilitasyon-gelecek-planlamasi' => ['aile-destegi', 'Özel Gereksinimli Çocuk İçin Gelecek Planlaması', 'Ailelerin özel gereksinimli çocukları için uzun vadeli planlama yaparken düşünmesi gereken konular: eğitim, bağımsız yaşam, mali güvence, yasal düzenlemeler ve bakım planı.'],
        'rehabilitasyon-cocuga-durumunu-anlatmak' => ['aile-destegi', 'Çocuğa Kendi Durumunu Anlatmak', 'Özel gereksinimli çocuğa kendi durumunu yaşına ve anlama düzeyine uygun şekilde anlatmak; doğru zaman, olumlu dil, güçlü yönler ve sorulara yanıt verme.'],
        'rehabilitasyon-kalabalik-ortamlar' => ['aile-destegi', 'Kalabalık Ortamlar ve Bayramlar: Özel Gereksinimli Çocukla Hazırlık', 'Bayram ziyaretleri, düğünler, alışveriş merkezleri gibi kalabalık ortamlara özel gereksinimli çocukla hazırlanmak; duyusal hassasiyetler, planlama ve sakinleşme stratejileri.'],
        'rehabilitasyon-doktor-randevusuna-hazirlik' => ['aile-destegi', 'Doktor ve Terapi Randevularına Hazırlık', 'Özel gereksinimli çocuğun doktor ve terapi randevularını verimli geçirmek için not hazırlama, belgeler, çocuğu hazırlamak, soru listesi ve randevu sonrası takip.'],
        'rehabilitasyon-ebeveyn-psikolojisi' => ['aile-destegi', 'Özel Gereksinimli Çocuğu Olan Ebeveynlerin Psikolojisi', 'Ebeveynlerin yaşayabileceği duygusal süreçler, kaygı ve stres kaynakları, kendine bakım, eş ilişkisi, sosyal destek ve profesyonel yardımın önemi.'],
        'rehabilitasyon-okula-hazirlik' => ['aile-destegi', 'Özel Gereksinimli Çocuğu Okula Hazırlamak', 'Özel gereksinimli çocuğun okula başlamasına hazırlık: okul seçimi, okulla iletişim, günlük becerilerin desteklenmesi, okul ziyareti, görsel hazırlık ve ilk günler.'],
        'rehabilitasyon-erisilebilir-ev-duzenlemesi' => ['evde-gunluk-yasam', 'Erişilebilir Ev Düzenlemesi', 'Hareket kısıtlılığı olan bireyler için evin erişilebilir hale getirilmesi: giriş, kapılar, zemin, banyo, mutfak, yatak odası ve aydınlatma önerileri.'],
        'rehabilitasyon-banyo-guvenligi' => ['evde-gunluk-yasam', 'Banyo Güvenliği: Hareket Kısıtlılığı Olan Bireyler İçin', 'Banyoda düşme ve yaralanma riskini azaltmak için tutunma barları, kaymaz zemin, duş oturağı, su sıcaklığı, transfer ve bakım veren desteği hakkında öneriler.'],
        'rehabilitasyon-beslenme-zorluklari' => ['evde-gunluk-yasam', 'Özel Gereksinimli Çocuklarda Beslenme Zorlukları', 'Seçici yeme, doku hassasiyeti, çiğneme ve yutma güçlükleri gibi beslenme zorlukları; sofra düzeni, sabırlı yaklaşım ve uzman desteği hakkında öneriler.'],
        'rehabilitasyon-uyku-rutini' => ['evde-gunluk-yasam', 'Özel Gereksinimli Çocuklarda Uyku Rutini', 'Özel gereksinimli çocuklarda sık görülen uyku sorunları, düzenli bir uyku rutini oluşturmak, yatak odası düzeni, görsel destekler ve doktora danışma.'],
        'rehabilitasyon-tuvalet-becerileri' => ['evde-gunluk-yasam', 'Özel Gereksinimli Çocuklarda Tuvalet Becerileri', 'Özel gereksinimli çocuklarda tuvalet eğitimine hazırlık, adım adım öğretim, görsel destekler, tutarlılık, kazalara yaklaşım ve okul ile iş birliği.'],
        'rehabilitasyon-giyinme-becerisi' => ['evde-gunluk-yasam', 'Giyinme Becerisi Nasıl Kazandırılır?', 'Özel gereksinimli çocuklara ve hareket kısıtlılığı olan bireylere giyinme becerisini adım adım öğretmek; uygun kıyafet seçimi, yardımcı araçlar ve sabırlı yaklaşım.'],
        'rehabilitasyon-evde-motor-oyunlar' => ['evde-gunluk-yasam', 'Evde Motor Becerileri Destekleyen Oyunlar', 'Özel gereksinimli çocukların kaba ve ince motor becerilerini evde destekleyen basit oyunlar, güvenlik önlemleri ve terapistle iş birliği hakkında öneriler.'],
        'rehabilitasyon-duyusal-duzenleme' => ['evde-gunluk-yasam', 'Duyusal Düzenleme: Evde Neler Yapılabilir?', 'Duyusal hassasiyeti olan çocuklar için duyusal düzenlemenin anlamı, aşırı ve az tepki işaretleri, evde sakin alan, duyusal etkinlikler ve ergoterapistle iş birliği.'],
        'rehabilitasyon-tekerlekli-sandalye-ile-ev' => ['evde-gunluk-yasam', 'Tekerlekli Sandalye ile Evde Yaşam', 'Tekerlekli sandalye kullanan bireyler için evde manevra alanı, mobilya düzeni, mutfak ve banyo kullanımı, sandalye bakımı, cilt sağlığı ve bağımsızlığı destekleyen öneriler.'],
        'rehabilitasyon-transfer-ve-tasima' => ['evde-gunluk-yasam', 'Transfer ve Taşıma: Güvenli Yer Değiştirme', 'Hareket kısıtlılığı olan bireylerin yataktan sandalyeye, sandalyeden tuvalete güvenli transferi; bakım verenin bel sağlığı, yardımcı araçlar ve profesyonel eğitimin önemi.'],
        'rehabilitasyon-gorsel-gunluk-cizelge' => ['evde-gunluk-yasam', 'Görsel Günlük Çizelge Nasıl Hazırlanır?', 'Özel gereksinimli çocuklar için görsel günlük çizelgenin faydaları, resim seçimi, çizelge türleri, evde kullanımı, değişikliklerin gösterilmesi ve okul ile ortak kullanım.'],
        'rehabilitasyon-sokakta-guvenlik' => ['evde-gunluk-yasam', 'Sokakta ve Toplum İçinde Güvenlik', 'Özel gereksinimli çocukların sokakta, parkta ve kalabalık yerlerde güvenliği: trafik becerileri, kaybolma riski, kimlik bilgisi, güvenli yetişkinler ve adım adım bağımsızlık.'],
        'rehabilitasyon-tatil-ve-seyahat' => ['evde-gunluk-yasam', 'Özel Gereksinimli Bireyle Tatil ve Seyahat', 'Özel gereksinimli çocuk ya da yetişkinle tatil planlama: erişilebilir konaklama, ulaşım, ilaç ve belgeler, rutinleri korumak, hazırlık ve beklentileri gerçekçi tutmak.'],
        'rehabilitasyon-alternatif-iletisim-araclari' => ['evde-gunluk-yasam', 'Alternatif ve Destekleyici İletişim Araçları', 'Konuşmakta zorlanan bireyler için alternatif ve destekleyici iletişim: işaretler, resimli iletişim kartları, iletişim panoları, cihaz ve uygulamalar, evde kullanım ve yaygın yanlış inanışlar.'],
        'rehabilitasyon-mevsim-gecislerinde-bakim' => ['evde-gunluk-yasam', 'Mevsim Geçişlerinde Bakım ve Rutin Uyumu', 'Özel gereksinimli bireylerde mevsim değişikliklerine uyum: sıcak ve soğuk havada dikkat edilecekler, kıyafet geçişi, gün ışığı ve rutin değişiklikleri, sağlık takibi.'],
        'rehabilitasyon-evde-sorumluluk-paylasimi' => ['evde-gunluk-yasam', 'Özel Gereksinimli Bireye Evde Sorumluluk Vermek', 'Özel gereksinimli çocuk ve yetişkinlerin ev işlerine katılımı: yaşa ve beceriye uygun görevler, adım adım öğretim, görsel destekler, takdir ve bağımsızlığa katkısı.'],
    ],
];
